<?php require __DIR__ . '/includes/config.php';if(is_logged_in())redirect('profile.php');if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email'])]);$user=$s->fetch();if($user&&password_verify($_POST['password'],$user['password'])){$_SESSION['user']=$user;redirect($user['role']==='admin'?'admin/index.php':'profile.php');}flash('danger','Email or password is incorrect.');}$pageTitle='Sign in';require __DIR__ . '/includes/header.php'; ?><section class="container py-5"><div class="row justify-content-center"><div class="col-md-5"><div class="panel"><div class="eyebrow">Welcome back</div><h1 class="h2 my-3">Sign in</h1><form method="post"><label class="form-label">Email</label><input required type="email" name="email" class="form-control mb-3"><label class="form-label">Password</label><input required type="password" name="password" class="form-control mb-4"><button class="btn btn-dark w-100">Sign in</button></form><p class="text-secondary mt-4 mb-0">New here? <a href="register.php">Create an account</a></p></div></div></div></section><?php require __DIR__ . '/includes/footer.php'; ?>